def calendar_concurrency_checks(cmd, env):
    import select
    import time
    prefix = [str(x) for x in cmd] + ['-A', '-t', '-q', '-v', 'VERBOSITY=verbose']
    owner = 'e0000000-0000-0000-0000-000000000001'
    pro = 'e0000000-0000-0000-0000-000000000002'
    dog = 'e0000000-0000-0000-0000-000000000101'
    service = 'e0000000-0000-0000-0000-000000000201'

    def sql(statement):
        result = subprocess.run(prefix, input=statement, text=True, capture_output=True, env=env, timeout=15)
        if result.returncode:
            raise RuntimeError(result.stderr)
        return result.stdout.strip()

    def as_user(uid, statement):
        return f"SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claim.sub','{uid}',true);\n{statement}\n"

    def pair(first_uid, first_sql, second_uid, second_sql, expected_error=None):
        first = second = None
        try:
            first = subprocess.Popen(prefix, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
            first.stdin.write(('BEGIN;'+as_user(first_uid, first_sql)+"SELECT 'PC_HOLDER_READY';\n").encode())
            first.stdin.flush()
            buffer = b''
            deadline = time.monotonic()+15
            while b'PC_HOLDER_READY' not in buffer:
                if time.monotonic()>deadline:
                    raise RuntimeError('Timeout della prima transazione')
                ready, _, _ = select.select([first.stdout], [], [], 0.2)
                if ready:
                    chunk = os.read(first.stdout.fileno(), 4096)
                    if not chunk:
                        raise RuntimeError('Prima transazione fallita: '+first.stderr.read().decode())
                    buffer += chunk
            second_env = dict(env, PGAPPNAME='pc_calendar_contender')
            second = subprocess.Popen(prefix, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=second_env)
            second.stdin.write(('BEGIN;'+as_user(second_uid, second_sql)+'COMMIT;\n').encode())
            second.stdin.close()
            second.stdin = None
            deadline = time.monotonic()+10
            blocked = False
            while time.monotonic()<deadline:
                blocked = sql("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE application_name='pc_calendar_contender' AND wait_event_type='Lock');") == 't'
                if blocked or second.poll() is not None:
                    break
                time.sleep(0.05)
            if not blocked:
                raise RuntimeError('Seconda transazione non osservata in attesa del lock')
            first.stdin.write(b'COMMIT;\n')
            first.stdin.close()
            first.stdin = None
            _, error = first.communicate(timeout=15)
            if first.returncode:
                raise RuntimeError('Primo commit fallito: '+error.decode())
            output, error = second.communicate(timeout=15)
            if expected_error is None:
                if second.returncode:
                    raise RuntimeError('Seconda transazione fallita: '+error.decode())
            elif second.returncode == 0 or expected_error not in error.decode():
                raise RuntimeError('SQLSTATE atteso '+expected_error+'; ottenuto '+error.decode())
            return output.decode().strip()
        finally:
            for process in [first, second]:
                if process is not None and process.poll() is None:
                    process.terminate()
                    try:
                        process.communicate(timeout=5)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.communicate(timeout=5)

    sql(f"""
      INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data) VALUES
      ('{owner}','calendar-race-owner@example.invalid',now(),'{{"pawconnect_onboarding_version":"1","full_name":"Race Owner","role":"owner"}}'),
      ('{pro}','calendar-race-pro@example.invalid',now(),'{{"pawconnect_onboarding_version":"1","full_name":"Race Pro","role":"professional","professional_type":"trainer"}}');
      UPDATE public.professionals SET approved=true,approval_status='approved' WHERE id='{pro}';
      INSERT INTO public.dogs(id,owner_id,name,breed) VALUES('{dog}','{owner}','Race Dog','Meticcio / altra razza');
      INSERT INTO public.services(id,professional_id,name,price,duration_minutes) VALUES('{service}','{pro}','Race service',25,60);
    """)
    day = sql("SELECT ((clock_timestamp() AT TIME ZONE 'Europe/Rome')::date+20)::text;")
    record = f"SELECT public.create_booking_with_dog('{service}','{dog}',('{day}'::date+time '10:00') AT TIME ZONE 'Europe/Rome','Race booking');"
    sql('BEGIN;'+as_user(owner, record)+'COMMIT;')
    booking = sql(f"SELECT id FROM public.bookings WHERE professional_id='{pro}';")
    accept = f"SELECT public.change_booking_status('{booking}','accepted');"
    period = 'e0000000-0000-0000-0000-000000000301'
    block = f"SELECT accepted_bookings FROM public.add_my_time_off('{period}','{day}','{day}','Race absence');"
    pair(pro, block, pro, accept, 'PCA02')
    if sql(f"SELECT status FROM public.bookings WHERE id='{booking}';") != 'pending':
        raise RuntimeError('Accettazione passata dopo un blocco concorrente')
    sql('BEGIN;'+as_user(pro, f"SELECT public.remove_my_time_off('{period}');")+'COMMIT;')
    result = pair(pro, accept, pro, block)
    if result.splitlines()[-1] != '1' or sql(f"SELECT status FROM public.bookings WHERE id='{booking}';") != 'accepted':
        raise RuntimeError('Appuntamento accettato prima del blocco non conservato/segnalato')
    sql('BEGIN;'+as_user(pro, f"SELECT public.remove_my_time_off('{period}');")+'COMMIT;')
    pair(pro, 'SELECT public.set_my_booking_pause(true);', owner, record, 'PCA01')
    if sql(f"SELECT count(*) FROM public.bookings WHERE professional_id='{pro}';") != '1':
        raise RuntimeError('Prenotazione creata dopo la sospensione concorrente')
    pair(pro, block, pro, block)
    if sql(f"SELECT count(*) FROM public.professional_time_off WHERE professional_id='{pro}';") != '1':
        raise RuntimeError('Doppio invio concorrente ha duplicato il periodo')
    print('OK: quattro casi concorrenti con due connessioni: blocco/accettazione, ordine inverso, pausa/prenotazione e retry.', flush=True)


